"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { Button as BaseButton } from "@base-ui/react/button";

import { mergeClassName } from "../shared/merge-class-name.js";
import { styles } from "./button.stylex.js";

const loadingIndicatorPath =
  "M10 4.99962C10 5.98589 9.70832 6.95013 9.16165 7.77103C8.61498 8.59193 7.83774 9.23282 6.92772 9.61307C6.0177 9.99331 5.01555 10.0959 4.04734 9.90802C3.07914 9.72011 2.18814 9.25005 1.48644 8.55698C0.784733 7.86392 0.303671 6.97881 0.103776 6.01301C-0.0961202 5.04721 -0.00592118 4.04387 0.363025 3.1292C0.731971 2.21454 1.36318 1.42942 2.17725 0.872625C2.99131 0.315826 3.95186 0.0122187 4.93806 0L4.9554 1.39989C4.24534 1.40869 3.55374 1.62729 2.96762 2.02818C2.38149 2.42908 1.92702 2.99436 1.66138 3.65292C1.39574 4.31148 1.33079 5.03388 1.47472 5.72926C1.61864 6.42464 1.96501 7.06191 2.47024 7.56092C2.97546 8.05993 3.61698 8.39837 4.31409 8.53367C5.01119 8.66897 5.73274 8.59508 6.38796 8.3213C7.04317 8.04752 7.60278 7.58608 7.99639 6.99503C8.38999 6.40398 8.6 5.70973 8.6 4.99962H10Z";

function DefaultLoadingIndicator() {
  const maskId = `button-spinner-${React.useId().replaceAll(":", "")}`;

  return (
    <svg
      aria-hidden="true"
      focusable="false"
      preserveAspectRatio="none"
      viewBox="0 0 10 9.99962"
      {...stylex.props(styles.spinner)}
    >
      <mask fill="white" id={maskId}>
        <path d={loadingIndicatorPath} />
      </mask>
      <path
        d={loadingIndicatorPath}
        mask={`url(#${maskId})`}
        stroke="currentColor"
        strokeWidth="3"
      />
    </svg>
  );
}

export type ButtonVariant = "primary" | "secondary" | "ghost" | "danger";
export type ButtonSize = "compact" | "default";

export interface ButtonProps extends Omit<BaseButton.Props, "children" | "className" | "disabled"> {
  children?: React.ReactNode;
  className?: BaseButton.Props["className"];
  disabled?: boolean;
  loading?: boolean;
  loadingIndicator?: React.ReactNode;
  size?: ButtonSize;
  variant?: ButtonVariant;
}

export const Button = React.forwardRef<HTMLElement, ButtonProps>(function Button(
  {
    children,
    className,
    disabled,
    loading = false,
    loadingIndicator,
    size = "compact",
    variant = "primary",
    ...props
  },
  ref,
) {
  const generated = stylex.props(
    styles.root,
    styles.rounded,
    styles[size],
    styles[variant],
  ).className;

  return (
    <BaseButton
      {...props}
      aria-busy={loading || undefined}
      className={mergeClassName(generated, className)}
      data-loading={loading ? "" : undefined}
      data-size={size}
      data-slot="button"
      data-variant={variant}
      disabled={disabled || loading}
      ref={ref}
    >
      {loading && (loadingIndicator === undefined ? <DefaultLoadingIndicator /> : loadingIndicator)}
      {children}
      <span
        aria-hidden="true"
        data-slot="button-state-layer"
        {...stylex.props(styles.stateLayer)}
      />
    </BaseButton>
  );
});

import * as stylex from "@stylexjs/stylex";

import { tokens } from "../tokens.stylex.js";

const spin = stylex.keyframes({
  to: { transform: "rotate(360deg)" },
});

export const stateLayer = stylex.defineVars({
  background: "transparent",
  border: "transparent",
});

export const styles = stylex.create({
  root: {
    [stateLayer.background]: {
      default: null,
      ":active": tokens.colorInteractionPressedOverlay,
      '[data-visual-state="pressed"]': tokens.colorInteractionPressedOverlay,
    },
    [stateLayer.border]: {
      default: null,
      ":focus-visible": tokens.colorFocusRing,
      '[data-visual-state="focus-visible"]': tokens.colorFocusRing,
    },
    alignItems: "center",
    borderStyle: "none",
    borderWidth: 0,
    boxSizing: "border-box",
    cursor: {
      default: "pointer",
      ":disabled": "default",
      '[data-visual-state="disabled"]': "default",
    },
    display: "inline-flex",
    flexShrink: 0,
    fontFamily: tokens.fontButton,
    fontWeight: 500,
    gap: tokens.space2,
    justifyContent: "center",
    lineHeight: "normal",
    outline: "none",
    opacity: {
      default: tokens.opacityEnabled,
      ":disabled": tokens.opacityDisabled,
      "[data-loading]": tokens.opacityEnabled,
      '[data-visual-state="disabled"]': tokens.opacityDisabled,
    },
    position: "relative",
    transitionDuration: "120ms",
    transitionProperty: "background-color, border-color, color, opacity",
    transitionTimingFunction: "ease-out",
    userSelect: "none",
    whiteSpace: "nowrap",
  },
  compact: {
    fontSize: "11px",
    height: tokens.sizeControlCompact,
    paddingInline: tokens.space3,
  },
  default: {
    fontSize: "12px",
    height: tokens.sizeControlDefault,
    paddingInline: tokens.space3,
  },
  rounded: { borderRadius: tokens.radiusRounded },
  primary: {
    backgroundColor: {
      default: tokens.colorActionPrimary,
      ":hover": tokens.colorActionPrimaryHover,
      ":active": tokens.colorActionPrimaryHover,
      ":disabled": tokens.colorActionPrimary,
      "[data-loading]": tokens.colorActionPrimary,
      '[data-visual-state="hover"]': tokens.colorActionPrimaryHover,
      '[data-visual-state="pressed"]': tokens.colorActionPrimaryHover,
    },
    boxShadow: "inset 0 0 0 0.5px var(--color-border-transparent, transparent)",
    color: tokens.colorActionPrimaryContent,
  },
  secondary: {
    backgroundColor: {
      default: tokens.colorSurfaceTranslucent,
      ":hover": tokens.colorSurfaceLevel3,
      ":active": tokens.colorSurfaceLevel3,
      ":disabled": tokens.colorSurfaceTranslucent,
      "[data-loading]": tokens.colorSurfaceTranslucent,
      '[data-visual-state="hover"]': tokens.colorSurfaceLevel3,
      '[data-visual-state="pressed"]': tokens.colorSurfaceLevel3,
    },
    boxShadow: "inset 0 0 0 0.5px var(--color-border-translucent, rgba(0, 0, 0, 0.08))",
    color: tokens.colorContentPrimary,
  },
  ghost: {
    backgroundColor: {
      default: "transparent",
      ":hover": tokens.colorSurfaceQuaternary,
      ":active": tokens.colorSurfaceQuaternary,
      ":disabled": "transparent",
      "[data-loading]": "transparent",
      '[data-visual-state="hover"]': tokens.colorSurfaceQuaternary,
      '[data-visual-state="pressed"]': tokens.colorSurfaceQuaternary,
    },
    boxShadow: "inset 0 0 0 0.5px var(--color-border-transparent, transparent)",
    color: tokens.colorContentTertiary,
  },
  danger: {
    backgroundColor: {
      default: tokens.colorActionDanger,
      ":hover": tokens.colorActionDangerHover,
      ":active": tokens.colorActionDangerHover,
      ":disabled": tokens.colorActionDanger,
      "[data-loading]": tokens.colorActionDanger,
      '[data-visual-state="hover"]': tokens.colorActionDangerHover,
      '[data-visual-state="pressed"]': tokens.colorActionDangerHover,
    },
    boxShadow: "inset 0 0 0 0.5px var(--color-border-transparent, transparent)",
    color: tokens.colorContentInverse,
  },
  spinner: {
    animationDuration: "650ms",
    animationIterationCount: "infinite",
    animationName: spin,
    animationTimingFunction: "linear",
    display: "block",
    fill: "none",
    flexShrink: 0,
    height: "10px",
    transformBox: "fill-box",
    transformOrigin: "center",
    width: "10px",
    "@media (prefers-reduced-motion: reduce)": {
      animationDuration: "1.5s",
    },
  },
  stateLayer: {
    backgroundColor: stateLayer.background,
    borderColor: stateLayer.border,
    borderRadius: "inherit",
    borderStyle: "solid",
    borderWidth: "1px",
    boxSizing: "border-box",
    inset: 0,
    pointerEvents: "none",
    position: "absolute",
  },
});

export type ClassName<State> = string | ((state: State) => string | undefined);

export function mergeClassName<State>(
  generated?: string,
  className?: ClassName<State>,
): ClassName<State> {
  if (typeof className === "function") {
    return (state) => [generated, className(state)].filter(Boolean).join(" ");
  }
  return [generated, className].filter(Boolean).join(" ");
}
